contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 wagerAmount, uint256 playDelayBlocks) public payable {
        require(wagerAmount == c.currentBetLimit(), "wagerAmount must equal current bet limit");
        require(address(this).balance >= wagerAmount, "insufficient balance to wager");

        c.OpenToThePublic();
        c.wager{value: wagerAmount}();

        bool wageredBefore = c.hasPlayerWagered(address(this));
        uint256 balanceBefore = address(c).balance;
        bool wonBefore = wageredBefore;

        uint256 targetBlock = block.number + playDelayBlocks;
        require(targetBlock > block.number, "block number overflow");

        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        bool wageredAfter = c.hasPlayerWagered(address(this));
        uint256 balanceAfter = address(c).balance;

        if (playReverted) {
            assert(wageredAfter == wageredBefore && balanceAfter == balanceBefore);
        } else {
            assert(!wageredAfter);
            uint256 payoutExpected = balanceBefore / 2;
            if (balanceAfter == balanceBefore - payoutExpected) {
                assert(true);
            } else if (balanceAfter == balanceBefore - (c.currentBetLimit() / 2)) {
                assert(true);
            } else {
                assert(false);
            }
        }
    }

    receive() external payable {}
}

